import {
  ArrowLeft,
  BookmarkPlus,
  Check,
  ChevronLeft,
  ChevronRight,
  CircleHelp,
  PenLine,
  RotateCcw,
  Shuffle,
  Sparkles,
  Trash2,
} from "lucide-react";
import { useEffect, useMemo, useState, type CSSProperties } from "react";
import { Navigate, useNavigate, useParams } from "react-router-dom";
import type { PracticeItem } from "@inkflow/shared";
import { cn } from "../../lib/cn";
import { useKnowledge } from "../../store/knowledge";
import { recordStudyEvent } from "../home/studyLog";
import {
  knowledgeBookById,
  moduleForNode,
  practiceForBook,
} from "../knowledge/knowledgeCatalog";
import {
  createCustomQuestion,
  loadCustomQuestions,
  saveCustomQuestions,
  type CustomPracticeQuestion,
} from "./practiceCustomQuestions";
import { practiceTrackById } from "./practiceTracks";
import "./practice-drill.css";

function normalizeAnswer(value: string) {
  return value
    .trim()
    .toLowerCase()
    .replace(/[.!?。！？]+$/g, "")
    .replace(/\s+/g, " ");
}

interface DrillQuestion {
  id: string;
  source: "bank" | "custom";
  moduleId?: string;
  kind: string;
  prompt: string;
  options: string[];
  answer: string;
  acceptedAnswers: string[];
  explanationZh: string;
  /** 题库题带原 PracticeItem，用于记学习台账；自建题没有。 */
  item?: PracticeItem;
}

function seedFrom(value: string, extra: number) {
  let hash = 2166136261;
  for (let index = 0; index < value.length; index += 1) {
    hash = Math.imul(hash ^ value.charCodeAt(index), 16777619);
  }
  return (hash ^ Math.imul(extra + 1, 2654435761)) >>> 0;
}

/** 种子洗牌：换章节/换顺序/点重新开始才重排，加自建题不打断当前题序。 */
function seededShuffle<T>(items: T[], seed: number): T[] {
  let state = seed >>> 0;
  const nextRandom = () => {
    state = (state + 0x6d2b79f5) >>> 0;
    let value = state;
    value = Math.imul(value ^ (value >>> 15), value | 1);
    value ^= value + Math.imul(value ^ (value >>> 7), value | 61);
    return ((value ^ (value >>> 14)) >>> 0) / 4294967296;
  };
  const next = [...items];
  for (let i = next.length - 1; i > 0; i -= 1) {
    const j = Math.floor(nextRandom() * (i + 1));
    [next[i], next[j]] = [next[j]!, next[i]!];
  }
  return next;
}

export function PracticeDrillPage() {
  const { trackId } = useParams();
  const navigate = useNavigate();
  const track = practiceTrackById(trackId);
  const book = knowledgeBookById(track?.bookId);
  const hydrate = useKnowledge((state) => state.hydrate);
  const recordAttempt = useKnowledge((state) => state.recordAttempt);

  const [moduleFilter, setModuleFilter] = useState<string>("all");
  const [orderMode, setOrderMode] = useState<"random" | "sequence">("random");
  const [queueSeed, setQueueSeed] = useState(0);
  const [questionIndex, setQuestionIndex] = useState(0);
  const [answer, setAnswer] = useState("");
  const [checked, setChecked] = useState<null | boolean>(null);
  const [feedback, setFeedback] = useState<string | null>(null);
  const [score, setScore] = useState({ correct: 0, wrong: 0 });
  const [customQuestions, setCustomQuestions] = useState<CustomPracticeQuestion[]>(
    loadCustomQuestions,
  );
  const [composerOpen, setComposerOpen] = useState(false);
  const [draftPrompt, setDraftPrompt] = useState("");
  const [draftAnswer, setDraftAnswer] = useState("");
  const [draftExplanation, setDraftExplanation] = useState("");

  useEffect(() => {
    void hydrate();
  }, [hydrate]);

  useEffect(() => {
    if (!track) return;
    recordStudyEvent({ kind: "open", at: Date.now(), bookId: track.bookId });
  }, [track]);

  const bank = useMemo<DrillQuestion[]>(() => {
    if (!book) return [];
    return practiceForBook(book).map((item) => ({
      id: item.id,
      source: "bank" as const,
      moduleId: moduleForNode(book, item.nodeId)?.id,
      kind: item.kind,
      prompt: item.prompt,
      options: item.options,
      answer: item.answer,
      acceptedAnswers: item.acceptedAnswers,
      explanationZh: item.explanationZh,
      item,
    }));
  }, [book]);

  const customAsQuestions = useMemo<DrillQuestion[]>(() => {
    if (!track) return [];
    return customQuestions
      .filter((question) => question.trackId === track.id)
      .map((question) => ({
        id: question.id,
        source: "custom" as const,
        kind: "short-answer",
        prompt: question.prompt,
        options: [],
        answer: question.answer,
        acceptedAnswers: [],
        explanationZh: question.explanationZh,
      }));
  }, [customQuestions, track]);

  const orderedBank = useMemo(() => {
    const filtered = bank.filter(
      (question) => moduleFilter === "all" || question.moduleId === moduleFilter,
    );
    if (orderMode !== "random") return filtered;
    return seededShuffle(filtered, seedFrom(moduleFilter, queueSeed));
  }, [bank, moduleFilter, orderMode, queueSeed]);

  // 自建题始终排在题库题后面，增删不会打乱题库题的当前顺序。
  const activeQuestions = useMemo(
    () => [...orderedBank, ...customAsQuestions],
    [orderedBank, customAsQuestions],
  );

  const total = activeQuestions.length;
  const safeIndex = total ? Math.min(questionIndex, total - 1) : 0;
  const current = activeQuestions[safeIndex];

  useEffect(() => {
    setQuestionIndex(0);
    setAnswer("");
    setChecked(null);
    setFeedback(null);
  }, [moduleFilter, orderMode, queueSeed]);

  if (!track || !book) return <Navigate to="/shelf" replace />;

  const answered = score.correct + score.wrong;
  const accuracy = answered
    ? Math.round((score.correct / answered) * 100)
    : 0;

  const checkAnswer = () => {
    if (!current || !answer.trim() || checked !== null) return;
    const correct = [current.answer, ...current.acceptedAnswers].some(
      (candidate) => normalizeAnswer(candidate) === normalizeAnswer(answer),
    );
    setChecked(correct);
    setFeedback(
      `${correct ? "Correct. " : "Not quite. "}${
        current.explanationZh || `参考答案：${current.answer}`
      }`,
    );
    setScore((state) => ({
      correct: state.correct + (correct ? 1 : 0),
      wrong: state.wrong + (correct ? 0 : 1),
    }));
    if (current.item) {
      recordAttempt(current.item, book.id, answer, correct);
      recordStudyEvent({
        kind: "knowledge-review",
        at: Date.now(),
        bookId: book.id,
        nodeId: current.item.nodeId,
        correct,
      });
    }
  };

  const nextQuestion = () => {
    if (!total) return;
    setQuestionIndex((index) => (index + 1) % total);
    setAnswer("");
    setChecked(null);
    setFeedback(null);
  };

  const restart = () => {
    setQueueSeed((seed) => seed + 1);
    setScore({ correct: 0, wrong: 0 });
  };

  const addCustomQuestion = () => {
    const prompt = draftPrompt.trim();
    const answerText = draftAnswer.trim();
    if (!prompt || !answerText) return;
    const question = createCustomQuestion({
      trackId: track.id,
      prompt,
      answer: answerText,
      explanationZh: draftExplanation,
    });
    setCustomQuestions((currentQuestions) => {
      const next = [question, ...currentQuestions];
      saveCustomQuestions(next);
      return next;
    });
    setDraftPrompt("");
    setDraftAnswer("");
    setDraftExplanation("");
    recordStudyEvent({ kind: "topic", at: Date.now(), bookId: book.id, topic: prompt.slice(0, 48) });
  };

  const removeCustomQuestion = (id: string) => {
    setCustomQuestions((currentQuestions) => {
      const next = currentQuestions.filter((question) => question.id !== id);
      saveCustomQuestions(next);
      return next;
    });
  };

  const trackCustomQuestions = customQuestions.filter(
    (question) => question.trackId === track.id,
  );
  const modules = book.modules;

  return (
    <main
      className="practice-drill"
      style={
        {
          "--drill-accent": track.accent,
        } as CSSProperties
      }
    >
      <aside className="practice-drill__rail">
        <button
          type="button"
          className="practice-drill__back"
          onClick={() => navigate("/practice")}
          aria-label="返回练习册"
        >
          <ArrowLeft size={17} />
        </button>
        <span className="knowledge-eyebrow">03 / Practice</span>
        <h1>{track.titleZh}</h1>
        <small>{track.title}</small>
        <p className="practice-drill__subtitle">{track.subtitleZh}</p>

        <div className="practice-drill__modules" aria-label="按章节筛选">
          <button
            type="button"
            className={cn(moduleFilter === "all" && "is-active")}
            onClick={() => setModuleFilter("all")}
          >
            全部
          </button>
          {modules.map((module) => (
            <button
              key={module.id}
              type="button"
              className={cn(moduleFilter === module.id && "is-active")}
              onClick={() => setModuleFilter(module.id)}
            >
              {module.titleZh}
            </button>
          ))}
        </div>

        <div className="practice-drill__custom">
          <button
            type="button"
            className="practice-drill__custom-toggle"
            onClick={() => setComposerOpen((open) => !open)}
          >
            <PenLine size={14} />
            自己出题 · {trackCustomQuestions.length}
          </button>
          {composerOpen ? (
            <div className="practice-drill__composer">
              <textarea
                rows={2}
                value={draftPrompt}
                placeholder="题干，例如：Spell the noun form of 'decide'."
                onChange={(event) => setDraftPrompt(event.target.value)}
              />
              <input
                value={draftAnswer}
                placeholder="答案（自动判分用）"
                onChange={(event) => setDraftAnswer(event.target.value)}
              />
              <input
                value={draftExplanation}
                placeholder="解析（可选）"
                onChange={(event) => setDraftExplanation(event.target.value)}
              />
              <button
                type="button"
                disabled={!draftPrompt.trim() || !draftAnswer.trim()}
                onClick={addCustomQuestion}
              >
                <BookmarkPlus size={14} />
                加入题库
              </button>
            </div>
          ) : null}
          {trackCustomQuestions.length ? (
            <ul className="practice-drill__custom-list">
              {trackCustomQuestions.map((question) => (
                <li key={question.id}>
                  <span>{question.prompt}</span>
                  <button
                    type="button"
                    onClick={() => removeCustomQuestion(question.id)}
                    aria-label="删除这道题"
                  >
                    <Trash2 size={13} />
                  </button>
                </li>
              ))}
            </ul>
          ) : null}
        </div>
      </aside>

      <section className="practice-drill__stage">
        <header className="practice-drill__masthead">
          <div>
            <span className="knowledge-eyebrow">
              {book.zhTitle} · 题库练习
            </span>
            <h2>{track.titleZh}练习册</h2>
          </div>
          <div className="practice-drill__score">
            <span>
              <Sparkles size={13} />
              {accuracy}% 正确 · 已做 {answered} 题
            </span>
            <small>
              对 {score.correct} / 错 {score.wrong}
            </small>
          </div>
        </header>

        <div className="practice-drill__card">
          <header className="practice-drill__card-head">
            <span>
              {current?.source === "custom" ? "自建" : current?.kind ?? "practice"}
            </span>
            <small>
              {safeIndex + 1} / {total || 0}
            </small>
          </header>

          {current ? (
            <>
              <strong className="practice-drill__prompt">{current.prompt}</strong>
              {current.options.length ? (
                <div className="practice-drill__options">
                  {current.options.map((option) => (
                    <label
                      key={option}
                      className={cn(
                        answer === option && "is-picked",
                        checked !== null &&
                          normalizeAnswer(option) === normalizeAnswer(current.answer) &&
                          "is-answer",
                      )}
                    >
                      <input
                        type="radio"
                        name={current.id}
                        checked={answer === option}
                        disabled={checked !== null}
                        onChange={() => setAnswer(option)}
                      />
                      <span>{option}</span>
                    </label>
                  ))}
                </div>
              ) : (
                <input
                  className="practice-drill__answer"
                  value={answer}
                  disabled={checked !== null}
                  placeholder="Write your answer…"
                  onChange={(event) => setAnswer(event.target.value)}
                  onKeyDown={(event) => {
                    if (event.key === "Enter") {
                      if (checked === null) checkAnswer();
                      else nextQuestion();
                    }
                  }}
                />
              )}
              {feedback ? (
                <p
                  className={cn(
                    "practice-drill__feedback",
                    checked === false && "is-wrong",
                  )}
                >
                  {checked ? <Check size={14} /> : <CircleHelp size={14} />}
                  {feedback}
                </p>
              ) : null}
              <div className="practice-drill__actions">
                {checked === null ? (
                  <button
                    type="button"
                    disabled={!answer.trim()}
                    onClick={checkAnswer}
                  >
                    <CircleHelp size={14} />
                    检查答案
                  </button>
                ) : (
                  <button type="button" onClick={nextQuestion}>
                    <ChevronRight size={14} />
                    下一题
                  </button>
                )}
                <button
                  type="button"
                  className="practice-drill__ghost"
                  onClick={() => {
                    setOrderMode((mode) =>
                      mode === "random" ? "sequence" : "random",
                    );
                  }}
                >
                  <Shuffle size={14} />
                  {orderMode === "random" ? "随机出题" : "顺序出题"}
                </button>
                <button
                  type="button"
                  className="practice-drill__ghost"
                  onClick={restart}
                >
                  <RotateCcw size={14} />
                  重新开始
                </button>
              </div>
            </>
          ) : (
            <p className="practice-drill__empty">
              这个章节还没有题目。切换章节，或在左边自己出几道。
            </p>
          )}
        </div>

        <footer className="practice-drill__footer">
          <button
            type="button"
            onClick={() => {
              if (!total) return;
              setQuestionIndex((safeIndex - 1 + total) % total);
              setAnswer("");
              setChecked(null);
              setFeedback(null);
            }}
            disabled={total < 2}
          >
            <ChevronLeft size={15} />
            上一题
          </button>
          <button
            type="button"
            onClick={() => navigate(`/book/${book.id}`)}
          >
            去看知识书 · {book.zhTitle}
          </button>
          <button
            type="button"
            onClick={nextQuestion}
            disabled={total < 2}
          >
            下一题
            <ChevronRight size={15} />
          </button>
        </footer>
      </section>
    </main>
  );
}
